# -*- coding: utf-8 -*-

import sys
from PyQt5.QtWidgets import QApplication, QMainWindow, QTableWidgetItem, QMessageBox
from PyQt5.uic import loadUi
from PyQt5.QtCore import QDate
import mysql.connector

class GestioneFatture(QMainWindow):
    def __init__(self):
        super().__init__()
        loadUi('GestioneFatture.ui', self)

        # Connessione al database MySQL
        self.conn = mysql.connector.connect(
            host="localhost",
            user="yourusername",
            password="yourpassword",
            database="ristorante"
        )
        self.cursor = self.conn.cursor()

        # Carica le fatture nella tabella basandosi sulla data odierna
        self.calendario.selectionChanged.connect(self.load_fatture)
        self.load_fatture()

        # Collegare i bottoni alle funzioni
        self.bt_rimuovi_fattura.clicked.connect(self.rimuovi_fattura)
        self.bt_mostra_info.clicked.connect(self.mostra_info_fattura)

    def load_fatture(self):
        selected_date = self.calendario.selectedDate().toString("yyyy-MM-dd")
        query = "SELECT Id, Data, Ora, Ricavo, Cameriere FROM fattura WHERE Data = %s"
        self.cursor.execute(query, (selected_date,))
        fatture = self.cursor.fetchall()

        self.tabella_fatture.setRowCount(0)
        for row_number, row_data in enumerate(fatture):
            self.tabella_fatture.insertRow(row_number)
            for column_number, data in enumerate(row_data):
                self.tabella_fatture.setItem(row_number, column_number, QTableWidgetItem(str(data)))

    def rimuovi_fattura(self):
        current_row = self.tabella_fatture.currentRow()
        if current_row >= 0:
            fattura_id = self.tabella_fatture.item(current_row, 0).text()
            self.cursor.execute("DELETE FROM fattura WHERE Id = %s", (fattura_id,))
            self.conn.commit()
            self.tabella_fatture.removeRow(current_row)
            QMessageBox.information(self, "Rimuovi Fattura", "Fattura rimossa con successo!")
        else:
            QMessageBox.warning(self, "Errore", "Seleziona una fattura da rimuovere.")

    def mostra_info_fattura(self):
        current_row = self.tabella_fatture.currentRow()
        if current_row >= 0:
            fattura_id = self.tabella_fatture.item(current_row, 0).text()
            self.info_fatture_window = InfoFatture(fattura_id)
            self.info_fatture_window.show()
        else:
            QMessageBox.warning(self, "Errore", "Seleziona una fattura per vedere le informazioni.")

class InfoFatture(QMainWindow):
    def __init__(self, fattura_id):
        super().__init__()
        loadUi('info_fatture.ui', self)

        # Connessione al database MySQL
        self.conn = mysql.connector.connect(
            host="localhost",
            user="yourusername",
            password="yourpassword",
            database="ristorante"
        )
        self.cursor = self.conn.cursor()

        # Carica le informazioni della fattura
        self.load_info_fattura(fattura_id)

    def load_info_fattura(self, fattura_id):
        self.cursor.execute("SELECT * FROM fattura WHERE Id = %s", (fattura_id,))
        fattura = self.cursor.fetchone()
        if fattura:
            self.label_id.setText(str(fattura[0]))
            self.label_data.setText(fattura[1])
            self.label_ora.setText(fattura[2])
            self.label_ricavo.setText(str(fattura[3]))
            self.label_cameriere.setText(fattura[4])
        else:
            QMessageBox.warning(self, "Errore", "Fattura non trovata.")



